CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE permissions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),code VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE roles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(255));
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),username VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,credentials_expired BOOLEAN NOT NULL DEFAULT FALSE,employee_id UUID);
CREATE TABLE user_roles(user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));